# forward_blocking_jatos.R
#
# Import, validate and save data sets generated by new studies conducted within
# the CATLAS project via JATOS.
#
# NOTE:
# In CATLAS, the experimental data are save to JATOS server trial-by-trial.
# This results in raw JATOS that have few perks, notably they have "json-like"
# structure with missing square brackets ("[]") around the data and missing
# commas between curly brackets ("{}") delineating data components. This script
# introduces a `raw2json()` function later coupled with {jsonlite} import to
# deal with this issue.

#library(catlasr)
library(tidyverse)
library(jatosR)
library(jsonlite)

# Make sure you have a valid JATOS API token before starting.
# If not, visit https://github.com/visionlabels/jatosR.git for instructions.


# --- 0. Set-up ----------------------------------------------
save_emails <- FALSE
study_id    <- "catlas_[01]"

url <- "https://jatos.mindprobe.eu"
tok <- Sys.getenv("mindprobe_catlas_token") # Saved via usethis::edit_r_environ()
bid <- c(29488)

.meta_cols <- c(
  "id", "sex", "age",
  "width", "height", "browser", "browser_version",
  "os", "vsync_rate"
)

.resp_cols <- c(
  "id",
  "stage", "block", "type",
  "cues", "response", "confidence", "rt1", "rt2",
  "correct_outcome", "is_correct", "timed_out"
)

.stim_labs <- c(
  LETTERS, "alpha", "beta", # cues
  paste0("o", 1:4)          # outcomes
)

.cues_map <- tribble(
  ~label, ~cue1, ~cue2, ~cues_reversed,
  "A" , "A",  NA, NA,
  "AB", "A", "B", FALSE,
  "BA", "A", "B", TRUE,
  "BK", "B", "K", FALSE,
  "KB", "B", "K", TRUE,
  "BN", "B", "N", FALSE,
  "NB", "B", "N", TRUE,
  "BT", "B", "T", FALSE,
  "TB", "B", "T", TRUE,
  "C" , "C",  NA, NA,
  "CD", "C", "D", FALSE,
  "DC", "C", "D", TRUE,
  "DK", "D", "K", FALSE,
  "KD", "D", "K", TRUE,
  "DN", "D", "N", FALSE,
  "ND", "D", "N", TRUE,
  "DQ", "D", "Q", FALSE,
  "QD", "D", "Q", TRUE,
  "E" , "E",  NA, NA,
  "EF", "E", "F", FALSE,
  "FE", "E", "F", TRUE,
  "FN", "F", "N", FALSE,
  "NF", "F", "N", TRUE,
  "FQ", "F", "Q", FALSE,
  "QF", "F", "Q", TRUE,
  "FT", "F", "T", FALSE,
  "TF", "F", "T", TRUE,
  "G" , "G",  NA, NA,
  "GH", "G", "H", FALSE,
  "HG", "G", "H", TRUE,
  "HK", "H", "K", FALSE,
  "KH", "H", "K", TRUE,
  "HQ", "H", "Q", FALSE,
  "QH", "H", "Q", TRUE,
  "HT", "H", "T", FALSE,
  "TH", "H", "T", TRUE,
  "I" , "I",  NA, NA,
  "JK", "J", "K", FALSE,
  "KJ", "J", "K", TRUE,
  "L" , "L",  NA, NA,
  "MN", "M", "N", FALSE,
  "NM", "M", "N", TRUE,
  "O" , "O",  NA, NA,
  "PQ", "P", "Q", FALSE,
  "QP", "P", "Q", TRUE,
  "R" , "R",  NA, NA,
  "ST", "S", "T", FALSE,
  "TS", "S", "T", TRUE,
  "UV", "U", "V", FALSE,
  "VU", "U", "V", TRUE,
  "WX", "W", "X", FALSE,
  "XW", "W", "X", TRUE,
  "YZ", "Y", "Z", FALSE,
  "ZY", "Y", "Z", TRUE,
  "alphabeta", "alpha", "beta", FALSE,
  "betaalpha", "alpha", "beta", TRUE
)

raw2json <- function(x) {
  output <- gsub("}{", "},{", x, fixed = TRUE)
  paste0("[", output, "]")
}


# --- 1. Download data from JATOS ----------------------------------------------
cc <- define_connection(url, tok)

test <- try(test_connection(cc), silent = TRUE)
if (inherits(test, "try-error")) {
  cli::cli_abort(c(
    "x" = "Connection test failed.",
    "i" = "Did you forget to specify a valid token?",
    "i" = "See https://github.com/visionlabels/jatosR.git"
  ))
}

jatos_data <-
  map_dfr(bid, function(batch) {
    meta <- get_metadata(jc = cc, batch_id = batch)
    results <- get_results (jc = cc, batch_id = batch)
    process_results(meta, results)$data
  })


# --- 2. Extract jsPsych data --------------------------------------------------
jspsych_data_all <-
  jatos_data |>
  mutate(data_jspsych = map2(data_raw, id_sr, function(d, i) {
    data <- d |>
      raw2json() |>
      fromJSON() |>
      try(silent = TRUE)

    if (inherits(data, "try-error")) {
      tibble(id = i, valid = FALSE, trial_type = "jatos-validation")
    } else {
      data |>
        mutate(id = i, .before = 1) |>
        full_join(
          tibble(id = i, valid = TRUE, trial_type = "jatos-validation"),
          by = c("id", "trial_type")
        )
    }
  })) |>
  select(data_jspsych) |>
  unnest(data_jspsych)


# --- 3. Locate valid and invalid runners --------------------------------------
jatos_valid_run <-
  jspsych_data_all |>
  filter(trial_type == "jatos-validation") |>
  pull(valid)

cli::cli_alert_info(paste0(
  "From a total of {length(jatos_valid_run)} JATOS runner{?s}, {.strong ",
  "{sum(jatos_valid_run)}} sampled valid jsPsych data and will be processed ",
  "further."
))


# --- 4. Extract meta-data -----------------------------------------------------
if (save_emails) {
  emails_csv <- here::here("data-raw", glue::glue("{study_id}_emails.csv"))
  cli::cli_alert_info(
    "Writing ID/e-mail pairs to {.file {emails_csv}}."
  )

  jspsych_data_all |>
    select(id, email) |>
    slice(which(jatos_valid_run)) |>
    write_csv(emails_csv)
}

meta_data <-
  jspsych_data_all |>
  select(all_of(.meta_cols)) |>
  group_by(id) |>
  fill(everything(), .direction = "downup") |>
  distinct(id, .keep_all = TRUE) |>
  ungroup() |>
  mutate(age = as.numeric(age)) |>
  slice(which(jatos_valid_run))


# --- 5. Extract stimuli mappings ----------------------------------------------
stimuli_mappings <-
  jspsych_data_all |>
  filter(trial_type == "stimuli-map") |>
  mutate(
    map = map2(cueMap, outcomeMap, function(x, y) {
      c <- as.data.frame(fromJSON(x))
      o <- as.data.frame(fromJSON(y))
      bind_cols(c, o)
    })
  ) |>
  unnest(map) |>
  select(id, all_of(.stim_labs)) |>
  mutate(
    across(o1:o4, \(x) str_extract(x, "^[^_]+"), .names = "{.col}_context"),
    across(o1:o4, \(x) str_extract(x, "[^_]+$"))
  )


# --- 6. Extract response data -------------------------------------------------
raw_response_data <-
  jspsych_data_all |>
  filter(trial_type == "experiment-trial") |>
  select(all_of(.resp_cols)) |>
  left_join(.cues_map, by = c("cues" = "label")) |>
  relocate(starts_with("cue"), .after = type) |>
  select(-cues)


# --- 7. Construct valid CATLAS jatos raw data bundle --------------------------
fb_online_replication <-
  catlasr:::catlas_jatos_rawdata(
    meta    = meta_data,
    stimuli = stimuli_mappings,
    trials  = raw_response_data
  ) |>
  catlasr:::validate_catlas_jatos_rawdata() |>
  catlasr:::validate_forward_blocking_rawdata()


# --- 8. Save the data bundle --------------------------------------------------
usethis::use_data(
  fb_online_replication,
  overwrite = TRUE
)
